#include<stdio.h>
int main(){
  int Q;
  scanf("%d",&Q);
  int A[101];
  int size=0;
  for(int i=0;i<Q;i++){
    int t,x;
    scanf("%d%d",&t,&x);
    if(t==1){
      A[size]=x;
      size++;
    }else{
      printf("%d\n",A[size-x]);
    }
  }
}

#include <iostream>
#include <vector>

using namespace std;

int main() {
    unsigned Q;
    cin >> Q;

    vector<unsigned> A; 
    for (unsigned i = 0; i < Q; ++i) {
        unsigned type;
        cin >> type;
        if (type == 1) { // 1 種類目のクエリでは
            unsigned value;
            cin >> value;
            A.emplace_back(value); // A の末尾に値を追加
        } else { // 2 種類目のクエリでは
            int value;
            cin >> value;
            cout << A.end()[-value] << endl; // A の後ろから value 番目の値を出力
        }
    }

    return 0;
}
